import React from 'react';
import {
  FaServer, FaChartLine, FaUniversity,
  FaUsers, FaProjectDiagram, FaDatabase,
  FaRobot, FaCloud
} from 'react-icons/fa';
import PixelCard from './PixelCard';
import './whyme.css';

const WHYME_AREAS = [
  { icon: <FaServer />, title: 'Distributed Systems', points: [
      '99.9% uptime microservices',
      'K8s/Terraform deployments',
      '20K+ tx/day'
  ]},
  { icon: <FaChartLine />, title: 'Observability', points: [
      'OpenTelemetry tracing',
      'Grafana dashboards',
      'Prometheus alerts'
  ]},
  { icon: <FaUniversity />, title: 'Academic Rigor', points: [
      'MSc AI research',
      'IEEE blockchain paper',
      '92% load accuracy'
  ]},
  { icon: <FaUsers />, title: 'Leadership', points: [
      '300+ devs trained',
      'RCA playbooks',
      'Hackathon spikes'
  ]},
  { icon: <FaProjectDiagram />, title: 'Systematic', points: [
      '95% TDD coverage',
      'Iterative prototypes',
      'Metrics-driven'
  ]},
  { icon: <FaDatabase />, title: 'Data Engineering', points: [
      '1M rows/day ETL',
      'Sub-second SQL',
      'Kafka+Spark dashboards'
  ]},
  { icon: <FaRobot />, title: 'Machine Learning', points: [
      'GRU navigation models',
      'Weather & AIS fusion',
      '85% RMSE drop'
  ]},
  { icon: <FaCloud />, title: 'Cloud Architecture', points: [
      'AWS Lambda serverless',
      'CloudFormation IaC',
      'OAuth2 & IAM'
  ]}
];

export default function WhyMe() {
  return (
    <section className="wm-section">
      <h1 className="wm-title">Why Choose Me?</h1>
      <div className="wm-grid">
        {WHYME_AREAS.map((a, i) => (
          <PixelCard key={i} variant="blue" className="wm-card">
  <div className="wm-card-overlay">
    <div className="wm-card-header">
      <div className="wm-icon">{a.icon}</div>
      <h2 className="wm-card-title">{a.title}</h2>
    </div>
    <ul className="wm-points">
      {a.points.map((p,j) => (
        <li key={j} className="wm-point">{p}</li>
      ))}
    </ul>
  </div>
</PixelCard>
        ))}
      </div>
    </section>
  );
}
