import React, { useState, useEffect, useRef } from 'react';
import './Certification.css';

// Dynamically import all images
const importAllImages = (requireContext) => {
  return requireContext.keys().map(requireContext);
};

const images = importAllImages(require.context('../certificates', false, /\.(png|jpe?g|gif)$/));

const Certification = () => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const autoPlayRef = useRef(null);

  // Auto-play functionality
  useEffect(() => {
    if (isAutoPlaying && images.length > 1) {
      autoPlayRef.current = setInterval(() => {
        goToNext();
      }, 4000); // Change certificate every 4 seconds
    }

    return () => {
      if (autoPlayRef.current) {
        clearInterval(autoPlayRef.current);
      }
    };
  }, [isAutoPlaying, currentIndex]);

  const goToNext = () => {
    if (isTransitioning) return;
    setIsTransitioning(true);
    setCurrentIndex((prevIndex) => (prevIndex + 1) % images.length);
    setTimeout(() => setIsTransitioning(false), 600);
  };

  const goToPrevious = () => {
    if (isTransitioning) return;
    setIsTransitioning(true);
    setCurrentIndex((prevIndex) => (prevIndex - 1 + images.length) % images.length);
    setTimeout(() => setIsTransitioning(false), 600);
  };

  const goToSlide = (index) => {
    if (isTransitioning || index === currentIndex) return;
    setIsTransitioning(true);
    setCurrentIndex(index);
    setTimeout(() => setIsTransitioning(false), 600);
  };

  // Get visible certificates (current, prev, next)
  const getVisibleCertificates = () => {
    const total = images.length;
    const prevIndex = (currentIndex - 1 + total) % total;
    const nextIndex = (currentIndex + 1) % total;
    
    return [
      { index: prevIndex, position: 'left' },
      { index: currentIndex, position: 'center' },
      { index: nextIndex, position: 'right' }
    ];
  };

  const handleMouseEnter = () => setIsAutoPlaying(false);
  const handleMouseLeave = () => setIsAutoPlaying(true);

  return (
    <div className="certification-container">
      <h1 className="HeadingCert">Certifications</h1>
      
      <div 
        className="carousel-modern-wrapper"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="carousel-track">
          {getVisibleCertificates().map(({ index, position }) => (
            <div
              key={`${index}-${position}`}
              className={`certificate-slide ${position} ${isTransitioning ? 'transitioning' : ''}`}
              onClick={() => position !== 'center' && goToSlide(index)}
            >
              <div className="certificate-card">
                <img
                  src={images[index]}
                  alt={`Certificate ${index + 1}`}
                  draggable={false}
                />
                <div className="certificate-overlay">
                  <span className="certificate-number">{index + 1} / {images.length}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Navigation Arrows */}
        <button 
          className="carousel-nav-btn prev-btn"
          onClick={goToPrevious}
          disabled={isTransitioning}
          aria-label="Previous certificate"
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </button>
        
        <button 
          className="carousel-nav-btn next-btn"
          onClick={goToNext}
          disabled={isTransitioning}
          aria-label="Next certificate"
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M9 18L15 12L9 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </button>

        {/* Dot Indicators
        <div className="carousel-indicators">
          {images.map((_, index) => (
            <button
              key={index}
              className={`indicator-dot ${index === currentIndex ? 'active' : ''}`}
              onClick={() => goToSlide(index)}
              aria-label={`Go to certificate ${index + 1}`}
            />
          ))}
        </div> */}

        {/* Progress Bar */}
        {/* <div className="carousel-progress">
          <div 
            className="progress-bar"
            style={{
              animation: isAutoPlaying ? 'progress 4s linear infinite' : 'none'
            }}
          />
        </div> */}
      </div>
    </div>
  );
};

export default Certification;
