import React from 'react'
import { motion } from 'framer-motion';
import Hello3D from './Hello3D';
import './Dashboard.css';
import Whyme from "./whyme"
import Projects from './Projects';
import Footer from "./Footer"
import Certification from './Certification';
import Contact from './Contact';
import MediumBlog from './MediumBlog';
import ScrollVelocity from './ScrollVelocity';
import AboutMe from './AboutMe';
import Experience from './Experience';
import LinkedInFeatured from './LinkedInFeatured';
// import LetterGlitch from './LetterGlitch';
  


const Dashboard = () => {



  const sectionVariants = {
      hidden: { opacity: 0, y: 50 },
      visible: { 
        opacity: 1, 
        y: 0,
        transition: { duration: 0.8, ease: "easeOut" }
      },exit: {
        opacity: 0,
        y: -50,
        transition: { duration: 0.5 }
      }
    };
  return (
    <div className="dashboard">
      
    <motion.section 
        id="home"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
      >
        
      <Hello3D />
    </motion.section>
    <motion.section
    id="aboutme"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
    >
      <AboutMe/>
    </motion.section>
    <motion.section
        id="whyme"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
      >
     <Whyme/>
    </motion.section>
    <motion.section
    id="experience"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
    >
      <Experience/>
    </motion.section>
    <motion.section
        id="projects"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
      >
      <Projects/>
    </motion.section>
    <motion.section
        id="certifications"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.4 }}
      >
        <Certification/>
      </motion.section>
      <motion.section
        id="mywork"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.2 }}
        style={{ backgroundColor: 'white' }}
      >
        <MediumBlog/>
      </motion.section>
      
    <motion.section
        id="contact"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.4 }}
      >
      
      <Contact/>
    </motion.section>
    <motion.section
        id="contact"
        initial="hidden"
        whileInView="visible"
        exit="exit"
        viewport={{ amount: 0.2, margin: "-50px" }}
        variants={sectionVariants}
        transition={{ delay: 0.4 }}
      >



            <div>
        <ScrollVelocity
  texts={['Lets Talk', 'AI and More |']} 
  velocity={100} 
  className="custom-scroll-text"
/>

</div> 
      </motion.section>


        
      
    
    <div
        id="findme"
       
      >
     <Footer/>
     </div>
     {/* <LetterGlitch
  glitchSpeed={50}
  centerVignette={true}
  outerVignette={false}
  smooth={true}
/> */}
    
  </div>
  )
}

export default Dashboard;
