// src/components/Experience.js
import React from 'react';
import ShinyText from './ShinyText';
import './Experience.css';

const education = [
  {
    degree: "Masters in Artificial Intelligence",
    institution: "National College of Ireland, Dublin",
    period: "2024 – 2025",
    description:
      "Graduated with 2:1 honors. Specialized in machine learning, computer vision, and deep learning. Thesis on maritime navigation prediction systems."
  },
  {
    degree: "B.Eng. in Computer Science",
    institution: "Vidyalankar Institute of Technology",
    period: "2020 – 2024",
    description:
      "Built strong foundations in algorithms, data structures, and full-stack development. Active hackathon participant."
  },
  {
    degree: "Higher Secondary Certificate (12th)",
    institution: "Maharashtra State Board",
    period: "2019 – 2020",
    description:
      "Science stream with distinction. Focused on mathematics, physics, and chemistry."
  },
  {
    degree: "Secondary School Certificate (10th)",
    institution: "Maharashtra State Board",
    period: "2017 – 2018",
    description:
      "Achieved Distinction grades. Developed early passion for technology."
  }
];

const work = [
  {
    role: "AI/ML Research Engineer",
    company: "Freelance Projects",
    period: "2024 – Present",
    description:
      "Developing maritime AI prediction systems, multimodal emotion detection, and supply-chain automation."
  },
  {
    role: "Teaching Assistant",
    company: "VIT",
    period: "2023 – 2024",
    description:
      "Assisted in Computer Networks course. Mentored students in networking and distributed systems."
  },
  {
    role: "M & E Porter -Part Time ",
    company: "Dalata Group of Hotels",
    period: "2024 – Present",
    description:
      "Part-time role managing event logistics alongside studies."
  },
  {
    role: "Software Dev Intern",
    company: "Various",
    period: "2021 – 2022",
    description:
      "Built full-stack React/Node.js apps and blockchain integration demos."
  }
];

export default function Experience() {
  return (
    <section className="exp-section">
      <div className="exp-container">
        <div className="exp-column">
          <h1><ShinyText text="Education" className="exp-heading" disabled={false} 
  speed={3} /></h1>
          {education.map((e, i) => (
            <div key={i} className="exp-item">
              <ShinyText text={e.degree} className="exp-title" />
              <ShinyText text={`${e.institution} | ${e.period}`} className="exp-subtitle" />
              <p className="exp-desc">{e.description}</p>
            </div>
          ))}
        </div>
        <div className="exp-column">
          <ShinyText text="Work Experience" disabled={false} 
  speed={3} className="exp-heading" />
          {work.map((w, i) => (
            <div key={i} className="exp-item">
              <ShinyText text={w.role} className="exp-title" />
              <ShinyText text={`${w.company} | ${w.period}`} className="exp-subtitle" />
              <p className="exp-desc">{w.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
