
import './App.css';


import { useEffect, useState,useRef } from 'react';
import FullScreenLoader from "./Pages/Loader";
import Navbar1 from './Pages/Navbar1';
import Dashboard from './Pages/Dashboard1';
import { Canvas } from '@react-three/fiber';
import ChatBot from './Pages/ChatBot';




const App = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [showChatIcon, setShowChatIcon] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const chatRef = useRef(null);
  const iconRef = useRef(null);

  // Handle clicks outside chat
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (showChat && 
          !chatRef.current?.contains(e.target) && 
          !iconRef.current?.contains(e.target)) {
        setShowChat(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showChat]);
  useEffect(() => {
    const fakeLoading = setTimeout(() => setIsLoading(false), 3000);
    return () => clearTimeout(fakeLoading);
  }, []);

  useEffect(() => {
    const fakeLoading = setTimeout(() => {
      setIsLoading(false);
      setTimeout(() => setShowChatIcon(true), 3000);
    }, 3000);
    
    return () => {
      clearTimeout(fakeLoading);
    };
  }, []);

 
  return (
    <div className="App">
      {isLoading ? <FullScreenLoader /> : null}
      <Canvas style={{ position: 'fixed', top: 0, left: 0 }}>
        Welcome
      </Canvas>
      
      <Navbar1/> 
      <Dashboard />
      {showChatIcon && (
       <div 
          ref={iconRef}
          className="thechat"
          onClick={(e) => {
            e.stopPropagation(); // Prevent event bubbling
            setShowChat(true); // Always open on click
          }}
          style={{ 
            cursor: 'pointer',
            width: '160px', 
            height: '100px',
            backgroundSize: 'cover',
            transition: 'opacity 0.3s',
            opacity: showChat ? 0.8 : 1
          }}
        >
         {showChat && (
        <div ref={chatRef}>
          <ChatBot  onClose={(e) => {
              e?.stopPropagation();
              setShowChat(false);
            }}  />
        </div>
      )}
        </div>
         )}
    </div>
  );
};


export default App;
