import { useState, useEffect } from 'react';

const ChatBot = ({ onClose }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [autoOpened, setAutoOpened] = useState(false);

  // Auto-open chat after 5 seconds
  useEffect(() => {
    const timer = setTimeout(() => {
      setAutoOpened(true);
      setMessages(prev => [...prev, 
        { text: 'Welcome! How can I help you today?', isBot: true }
      ]);
    }, 5000);
    return () => clearTimeout(timer);
  }, []);

  const handleSend = async () => {
    if (!input.trim()) return;

    // Add user message
    setMessages(prev => [...prev, { text: input, isBot: false }]);
    
    // Simulate bot response
    setTimeout(() => {
      const botResponse = generateResponse(input);
      setMessages(prev => [...prev, { text: botResponse, isBot: true }]);
    }, 1000);

    setInput('');
  };

  const generateResponse = (message) => {
    const lowerMsg = message.toLowerCase();
    
    if (lowerMsg.includes('hello') || lowerMsg.includes('hi')) {
      return 'Hello! How can I assist you?';
    }
    if (lowerMsg.includes('help')) {
      return 'I can help with general inquiries. What do you need assistance with?';
    }
    if (lowerMsg.includes('contact')) {
      return 'You can contact us at support@example.com';
    }
    return 'Thank you for your message. Our team will get back to you shortly.';
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        <h3>Chat Support</h3>
        <button onClick={onClose} className="close-btn">×</button>
      </div>
      
      <div className="chat-messages">
        {messages.map((msg, index) => (
          <div 
            key={index}
            className={`message ${msg.isBot ? 'bot' : 'user'}`}
          >
            {msg.text}
          </div>
        ))}
      </div>

      <div className="chat-input">
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Type your message..."
        />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
};

export default ChatBot;
