// src/components/LinkedInFeatured.js
import React, { useState, useEffect } from 'react';
import './LinkedInFeatured.css';
import { FaLinkedin, FaQuoteLeft, FaExternalLinkAlt } from 'react-icons/fa';

const FEATURED_POSTS = [
  {
    id: 1,
    author: "Hiring Manager",
    role: "Senior Engineering Manager at Google",
    avatar: "https://via.placeholder.com/60", // Replace with actual image
    content: "Rajat's approach to solving complex ML problems is remarkable. His maritime navigation system reduced errors by 85% - truly impressive work!",
    linkedInUrl: "https://linkedin.com/in/rajat-amate",
    type: "recommendation"
  },
  {
    id: 2,
    author: "Tech Lead",
    role: "Principal Engineer at Microsoft",
    avatar: "https://via.placeholder.com/60",
    content: "Working with Rajat on distributed systems was a pleasure. His expertise in K8s and observability helped us achieve 99.9% uptime.",
    linkedInUrl: "https://linkedin.com/in/rajat-amate",
    type: "recommendation"
  },
  {
    id: 3,
    author: "Colleague",
    role: "ML Engineer at Amazon",
    avatar: "https://via.placeholder.com/60",
    content: "Rajat's ability to explain complex AI concepts in simple terms is unmatched. He trained 300+ developers and the feedback was phenomenal!",
    linkedInUrl: "https://linkedin.com/in/rajat-amate",
    type: "testimonial"
  },
  {
    id: 4,
    author: "Team Member",
    role: "Software Engineer at IBM",
    avatar: "https://via.placeholder.com/60",
    content: "His systematic approach and 95% TDD coverage set the standard for our team. Rajat is a true professional in every sense.",
    linkedInUrl: "https://linkedin.com/in/rajat-amate",
    type: "testimonial"
  },
  {
    id: 5,
    author: "Research Advisor",
    role: "Professor at University",
    avatar: "https://via.placeholder.com/60",
    content: "Rajat's IEEE blockchain paper demonstrated exceptional research ability. His academic rigor combined with practical experience is rare.",
    linkedInUrl: "https://linkedin.com/in/rajat-amate",
    type: "recommendation"
  }
];

const LinkedInFeatured = () => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  useEffect(() => {
    if (isPaused) return;

    const interval = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % FEATURED_POSTS.length);
    }, 4000); // Rotate every 4 seconds

    return () => clearInterval(interval);
  }, [isPaused]);

  const handleCardClick = (index) => {
    setActiveIndex(index);
  };

  const handleViewLinkedIn = () => {
    window.open('https://linkedin.com/in/rajat-amate', '_blank');
  };

  return (
    <section className="linkedin-featured">
      <div className="lf-header">
        <h2 className="lf-title">What People Say</h2>
        <p className="lf-subtitle">Featured recommendations and testimonials</p>
      </div>

      <div 
        className="lf-cards-container"
        onMouseEnter={() => setIsPaused(true)}
        onMouseLeave={() => setIsPaused(false)}
      >
        <div className="lf-stack">
          {FEATURED_POSTS.map((post, index) => {
            const offset = (index - activeIndex + FEATURED_POSTS.length) % FEATURED_POSTS.length;
            const isActive = offset === 0;
            
            return (
              <div
                key={post.id}
                className={`lf-card ${isActive ? 'active' : ''}`}
                style={{
                  '--offset': offset,
                  zIndex: FEATURED_POSTS.length - offset,
                  transform: `
                    translateY(${offset * 15}px) 
                    translateX(${offset * -8}px) 
                    scale(${1 - offset * 0.05}) 
                    rotateZ(${offset * -2}deg)
                  `,
                  opacity: offset < 3 ? 1 - offset * 0.2 : 0,
                  pointerEvents: offset < 3 ? 'auto' : 'none'
                }}
                onClick={() => handleCardClick(index)}
              >
                <div className="lf-card-header">
                  <img src={post.avatar} alt={post.author} className="lf-avatar" />
                  <div className="lf-author-info">
                    <h3 className="lf-author">{post.author}</h3>
                    <p className="lf-role">{post.role}</p>
                  </div>
                  <FaLinkedin className="lf-linkedin-icon" />
                </div>

                <div className="lf-card-body">
                  <FaQuoteLeft className="lf-quote-icon" />
                  <p className="lf-content">{post.content}</p>
                </div>

                {isActive && (
                  <a
                    href={post.linkedInUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="lf-view-link"
                    onClick={(e) => e.stopPropagation()}
                  >
                    View on LinkedIn <FaExternalLinkAlt />
                  </a>
                )}
              </div>
            );
          })}
        </div>

        {/* Navigation dots */}
        <div className="lf-dots">
          {FEATURED_POSTS.map((_, index) => (
            <button
              key={index}
              className={`lf-dot ${index === activeIndex ? 'active' : ''}`}
              onClick={() => handleCardClick(index)}
              aria-label={`Go to testimonial ${index + 1}`}
            />
          ))}
        </div>
      </div>

      <button className="lf-linkedin-btn" onClick={handleViewLinkedIn}>
        <FaLinkedin /> View All on LinkedIn
      </button>
    </section>
  );
};

export default LinkedInFeatured;
